require dirname(__DIR__).'/config/bootstrap.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['super_admin','admin_lab']);verify_csrf();$id=(int)($_POST['id']??0);
 if(($_POST['action']??'')==='delete'){try{$pdo->prepare('DELETE FROM proyek WHERE id=?')->execute([$id]);audit($pdo,'Menghapus proyek','proyek',$id);flash('success','Proyek dihapus.');}catch(PDOException $e){error_log($e->getMessage());flash('danger','Proyek tidak dapat dihapus karena masih memiliki titik sondir.');}redirect('proyek/index.php');}
 $data=[(int)$_POST['klien_id'],trim($_POST['kode_proyek']??''),trim($_POST['nama_proyek']),trim($_POST['nama_pekerjaan']??''),trim($_POST['alamat_lokasi']??''),trim($_POST['kabupaten']??''),$_POST['tanggal_mulai']?:null,$_POST['tanggal_selesai']?:null,(int)($_POST['operator_id']??0)?:null,(int)($_POST['pemeriksa_id']??0)?:null,$_POST['status']??'draft',trim($_POST['catatan']??'')];
 if($data[1]==='')$data[1]='PRJ-'.date('Y').'-'.str_pad((string)((int)$pdo->query('SELECT COALESCE(MAX(id),0)+1 FROM proyek')->fetchColumn()),4,'0',STR_PAD_LEFT);
 if($id){$pdo->prepare('UPDATE proyek SET klien_id=?,kode_proyek=?,nama_proyek=?,nama_pekerjaan=?,alamat_lokasi=?,kabupaten=?,tanggal_mulai=?,tanggal_selesai=?,operator_id=?,pemeriksa_id=?,status=?,catatan=?,updated_at=NOW() WHERE id=?')->execute([...$data,$id]);}
 else{$pdo->prepare('INSERT INTO proyek(klien_id,kode_proyek,nama_proyek,nama_pekerjaan,alamat_lokasi,kabupaten,tanggal_mulai,tanggal_selesai,operator_id,pemeriksa_id,status,catatan,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$data,$_SESSION['user']['id']]);$id=(int)$pdo->lastInsertId();}
 audit($pdo,'Menyimpan proyek','proyek',$id,null,$data);flash('success','Proyek berhasil disimpan.');redirect('proyek/index.php');
}
$edit=null;if($eid=(int)($_GET['id']??0)){$q=$pdo->prepare('SELECT * FROM proyek WHERE id=?');$q->execute([$eid]);$edit=$q->fetch();}
$clients=$pdo->query('SELECT id,kode_klien,nama_klien FROM klien ORDER BY nama_klien')->fetchAll();$users=$pdo->query("SELECT id,nama_lengkap,level FROM users WHERE status='aktif' ORDER BY nama_lengkap")->fetchAll();
$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT p.*,k.nama_klien,(SELECT COUNT(*) FROM titik_sondir t WHERE t.proyek_id=p.id AND t.parent_id IS NULL) jumlah_titik FROM proyek p JOIN klien k ON k.id=p.klien_id WHERE p.nama_proyek LIKE ? OR p.kode_proyek LIKE ? ORDER BY p.id DESC");$st->execute(["%$q%","%$q%"]);$rows=$st->fetchAll();$pageTitle='Proyek';require APP_ROOT.'/includes/header.php';
?>
<div class="page-heading"><div><span class="eyebrow">Pelaksanaan</span><h2>Data Proyek</h2><p>Kelola pekerjaan, lokasi, dan penugasan personel.</p></div><?php if(can(['super_admin','admin_lab'])):?><button class="btn btn-primary btn-action" data-bs-toggle="modal" data-bs-target="#formModal"><i class="bi bi-plus-lg"></i> Tambah proyek</button><?php endif;?></div>
