tor</label><select class="form-select" name="operator_id"><option value="">Pilih</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=($edit['operator_id']??0)==$u['id']?'selected':''?>><?=e($u['nama_lengkap'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Pemeriksa</label><select class="form-select" name="pemeriksa_id"><option value="">Pilih</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=($edit['pemeriksa_id']??0)==$u['id']?'selected':''?>><?=e($u['nama_lengkap'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['draft','berjalan','selesai','diarsipkan','dibatalkan'] as $s):?><option <?=($edit['status']??'draft')===$s?'selected':''?> value="<?=$s?>"><?=ucwords($s)?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Catatan</label><textarea class="form-control" name="catatan"><?=e($edit['catatan']??'')?></textarea></div></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div></div>
